return {["scripts/actions/weaponskills/penta_thrust.lua"]={["Path"]="scripts/actions/weaponskills/penta_thrust.lua",["SHA256"]="d74f411dba7c5ef4a926562b5eeb4007ce0bb4f095ae351304de3a89ce041fa0",["Text"]="-----------------------------------\n-- Penta Thrust\n-- Polearm weapon skill\n-- Skill Level: 150\n-- Delivers a five-hit attack. params.accuracy varies with TP.\n-- 0.875 Attack penalty\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget.\n-- Aligned with the Shadow Belt.\n-- Element: None\n-- Modifiers: STR:20%  DEX:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 5\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.2 params.dex_wsc = 0.2\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n    params.atkVaries = { 0.875, 0.875, 0.875 }\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/piercing_arrow.lua"]={["Path"]="scripts/actions/weaponskills/piercing_arrow.lua",["SHA256"]="0f0e4106275d82cffdf10a4dcc5970efdfb0f2f54252ef7b26c7cc67fbb591df",["Text"]="-----------------------------------\n-- Piercing Arrow\n-- Archery weapon skill\n-- Skill level: 40\n-- Ignores enemy's defense. Amount ignored varies with TP.\n-- The amount of defense ignored is 0% with 100TP, 35% with 200TP and 50% with 300TP.\n-- Typically does less damage than Flaming Arrow.\n-- Aligned with the Snow Gorget & Light Gorget.\n-- Aligned with the Snow Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR:20%  AGI:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params               = {}\n    params.numHits             = 1\n    params.ftpMod              = { 1.0, 1.0, 1.0 }\n    params.str_wsc             = 0.16 params.agi_wsc = 0.25\n    params.rangedAccuracyBonus = 30 -- https://www.ffxiah.com/forum/topic/52018/luck-of-the-draw-a-corsairs-guide-new/127/#3726841 (split shot is a clone of piercing arrow)\n\n    -- Defense ignored is 0%, 35%, 50% as per wiki.bluegartr.com\n    params.ignoredDefense = { 0.0, 0.35, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.2 params.agi_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/power_slash.lua"]={["Path"]="scripts/actions/weaponskills/power_slash.lua",["SHA256"]="96e7f5be7fec382436aeb9245344fc96790f81d81b113c3db3f10af0067aff4d",["Text"]="-----------------------------------\n-- Power Slash\n-- Great Sword weapon skill\n-- Skill level: 30\n-- Delivers a single-hit attack. params.crit varies with TP.\n-- Modifiers: STR:60%  VIT:60%\n-- 100%TP     200%TP     300%TP\n-- 1.0         1.0        1.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    -- ftp damage mods (for Damage Varies with TP lines are calculated in the function\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    -- wscs are in % so 0.2=20%\n    params.str_wsc = 0.2 params.vit_wsc = 0.2\n    params.critVaries = { 0.2, 0.4, 0.6 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6 params.vit_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/primal_rend.lua"]={["Path"]="scripts/actions/weaponskills/primal_rend.lua",["SHA256"]="d74b0797cf75c587a071b0fd3b1bcdb18ef36965e09b7a4693e629e9db9f87e7",["Text"]="-----------------------------------\n-- Primal Rend\n-- Axe weapon skill\n-- Skill Level: N/A\n-- Deals light elemental damage. Damage varies with TP. Aymur: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Beastmaster) quest.\n-- Aligned with the Shadow Gorget, Soil Gorget & Aqua Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Aqua Belt.\n-- Element: Light\n-- Modifiers: CHR:60% DEX:30%\n-- 100%TP    200%TP    300%TP\n-- 3.0625    5.8398    7.5625\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 4.0, 4.25, 4.75 }\n    params.chr_wsc = 0.3\n    params.ele = xi.element.LIGHT\n    params.skill = xi.skill.AXE\n    params.includemab = true\n    params.dStat = xi.mod.CHR -- TODO : Verify maximum bonus of 651\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.0625, 5.8398, 7.5625 }\n        params.dex_wsc = 0.3 params.chr_wsc = 0.6\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/pyrrhic_kleos.lua"]={["Path"]="scripts/actions/weaponskills/pyrrhic_kleos.lua",["SHA256"]="a8e53fda402690291e97fd39db9f1d15f9067d51c98a85fe35b3203854961f34",["Text"]="-----------------------------------\n-- Pyrrhic Kleos\n-- Dagger weapon skill\n-- Skill level: N/A\n-- Description: Delivers a fourfold attack that lowers target's evasion. Duration of effect varies with TP. Terpsichore: Aftermath effect varies with TP.\n-- Available only after completing the Unlocking a Myth (Dancer) quest.\n-- Aligned with the Soil Gorget, Aqua Gorget & Snow Gorget.\n-- Aligned with the Soil Belt, Aqua Belt & Snow Belt.\n-- Element: Unknown\n-- Skillchain Properties: Distortion/Scission\n-- Modifiers: STR:40%  DEX:40%\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n-- 1.5        1.5        1.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 4\n    params.ftpMod  = { 1.5, 1.5, 1.5 }\n    params.str_wsc = 0.2\n    params.dex_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/15896.html\n        params.ftpMod      = { 1.75, 1.75, 1.75 }\n        params.str_wsc     = 0.4\n        params.dex_wsc     = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Apply Aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.MYTHIC)\n\n    -- Handle status effect\n    local effectId      = xi.effect.EVASION_DOWN\n    local actionElement = xi.element.ICE\n    local power         = 10\n    local duration      = math.floor(6 * tp / 100 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/quietus.lua"]={["Path"]="scripts/actions/weaponskills/quietus.lua",["SHA256"]="3092b3fe6f24fd02d8f76a97076a4861434ca4d262a8fa917e855a4fe39d81b2",["Text"]="-----------------------------------\n-- Quietus\n-- Scythe weapon skill\n-- Skill Level: N/A\n-- Delivers a triple damage attack that ignores target's defense. Amount ignored varies with TP. Redemption: Aftermath.\n-- Available only when equipped with Redemption (85)/(90)/(95)/(99) or Penitence +1/+2/+3/Umiliati.\n-- Aligned with the Shadow Gorget, Aqua Gorget & Snow Gorget.\n-- Aligned with the Shadow Belt, Aqua Belt & Snow Belt.\n-- Element: None\n-- Modifiers: STR: 60% MND: 60%\n-- 100%TP    200%TP    300%TP\n-- 3.00        3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.str_wsc = 0.4 params.mnd_wsc = 0.4\n    params.ignoredDefense = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6 params.mnd_wsc = 0.6\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/raging_axe.lua"]={["Path"]="scripts/actions/weaponskills/raging_axe.lua",["SHA256"]="32b38fc55a20632131b3af4ed99b741258e823e2dd930d4fc0a68911e8156d57",["Text"]="-----------------------------------\n-- Raging Axe\n-- Axe weapon skill\n-- Skill level: 5\n-- Delivers a two-hit attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- When stacked with Sneak Attack, both hits have a 100% chance of landing, though it is unclear if they both params.crit.\n-- Aligned with the Breeze Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:60%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.50      2.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/raging_fists.lua"]={["Path"]="scripts/actions/weaponskills/raging_fists.lua",["SHA256"]="7a349a2632f32dcde0b3c292322794a587d3a2e49f4634fde7a5dde867c3f021",["Text"]="-----------------------------------\n-- Raging Fists\n-- Hand-to-Hand weapon skill\n-- Skill Level: 125\n-- Delivers a fivefold attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:20%  DEX:20%\n-- 100%TP    200%TP    300%TP\n-- 1.00       1.5        2\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 5\n    params.ftpMod = { 1.0, 1.5, 2.0 }\n    params.str_wsc = 0.2 params.dex_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.multiHitfTP = true -- http://wiki.ffo.jp/html/2420.html\n        params.ftpMod = { 1.0, 2.1875, 3.75 }\n        params.str_wsc = 0.3 params.dex_wsc = 0.3\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/raging_rush.lua"]={["Path"]="scripts/actions/weaponskills/raging_rush.lua",["SHA256"]="c426b89ec8ba86d878deac2eb89ec799593d0a6d4992d2343ee9f7463e6d0f63",["Text"]="-----------------------------------\n-- Raging Rush\n-- Great Axe weapon skill\n-- Skill level: 200 (Warriors only.)\n-- Delivers a three-hit attack. Chance of params.critical hit varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Snow Gorget & Aqua Gorget.\n-- Aligned with the Snow Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 3\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.str_wsc = 0.35\n    params.critVaries = { 0.1, 0.3, 0.5 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.critVaries = { 0.15, 0.3, 0.5 }\n        params.str_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/raiden_thrust.lua"]={["Path"]="scripts/actions/weaponskills/raiden_thrust.lua",["SHA256"]="bffdd227260cf3e9ef256e91f18c66e1d1d78c11769475b392a579a8b826d98e",["Text"]="-----------------------------------\n-- Raiden Thrust\n-- Polearm weapon skill\n-- Skill Level: 70\n-- Deals lightning elemental damage to enemy. Damage varies with TP.\n-- Aligned with the Light Gorget & Thunder Gorget.\n-- Aligned with the Light Belt & Thunder Belt.\n-- Element: Lightning\n-- Modifiers: STR:40%  INT:40%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.0, 3.0 }\n    params.str_wsc = 0.3 params.int_wsc = 0.3\n    params.ele = xi.element.THUNDER\n    params.skill = xi.skill.POLEARM\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/rampage.lua"]={["Path"]="scripts/actions/weaponskills/rampage.lua",["SHA256"]="bfcb416b16c1feeb55e6857a7ddb9a1d22a72a3bac28ec9f325c0e2382dea5fe",["Text"]="-----------------------------------\n-- Rampage\n-- Axe weapon skill\n-- Skill level: 175\n-- Delivers a five-hit attack. Chance of params.critical varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: None\n-- Modifiers: STR:50%\n-- 100%TP    200%TP    300%TP\n--   1         1         1\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 5\n    params.ftpMod = { 0.5, 0.5, 0.5 }\n    params.str_wsc = 0.3\n    params.critVaries = { 0.10, 0.30, 0.50 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.0, 1.0, 1.0 }\n        params.str_wsc = 0.5\n        params.critVaries = { 0.0, 0.20, 0.40 }\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/randgrith.lua"]={["Path"]="scripts/actions/weaponskills/randgrith.lua",["SHA256"]="701e15905d32f17887a47bb8db3577c5bc4c9629779a1e5883fce036056856dd",["Text"]="-----------------------------------\n-- Randgrith\n-- Club weapon skill\n-- Skill level: N/A\n-- Lowers target's evasion. Gullintani/Mjollnir: Temporarily improves params.accuracy.\n-- Available only when equipped with the Relic Weapons Gullintani (Dynamis use only), Mjollnir, or a Charged Molva Maul.\n-- Aftermath: Adds +20 params.accuracy after the weapon skill is used, duration is determined by TP. Only available with Gullintani and Mjollnir.\n-- 100% = 20 seconds, 200% = 40 seconds, 300% = 60 seconds.\n-- This Relic Weapon is only available to White Mages Scholars must use the Molva Maul to acquire this weapon skill.\n-- Shield Break effect : Evasion -32\n-- Aligned with the Breeze Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: STR:40%  MND:40%\n-- 100%TP    200%TP    300%TP\n-- 2.75      2.75      2.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 2.75, 2.75, 2.75 }\n    params.str_wsc = 0.4\n    params.mnd_wsc = 0.4\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    -- Handle status effect\n    local effectId      = xi.effect.EVASION_DOWN\n    local actionElement = xi.element.ICE\n    local power         = 32\n    local duration      = math.floor(120 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/realmrazer.lua"]={["Path"]="scripts/actions/weaponskills/realmrazer.lua",["SHA256"]="6f7a6b60cb178cc360257cc0e6edc5668a66cd21c41e1c63030e7c1172dbe661",["Text"]="-----------------------------------\n-- Realmrazer\n-- Club weapon skill\n-- Skill Level: 357\n-- Delivers a seven-hit attack. params.accuracy varies with TP.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget & Soil Gorget.\n-- Aligned with the Shadow Belt & Soil Belt.\n-- Element: None\n-- Modifiers: MND:73~85%\n-- 100%TP    200%TP    300%TP\n-- .88        .88       .88\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 7\n    params.ftpMod = { 0.88, 0.88, 0.88 }\n    params.mnd_wsc = player:getMerit(xi.merit.REALMRAZER) * 0.17\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.mnd_wsc = 0.7 + (player:getMerit(xi.merit.REALMRAZER) * 0.03)\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/red_lotus_blade.lua"]={["Path"]="scripts/actions/weaponskills/red_lotus_blade.lua",["SHA256"]="2e5292044c8b2c5d31f6e4d619e8d54b50c532dbee3ee30aaf6acba38a057714",["Text"]="-----------------------------------\n-- Red Lotus Blade\n-- Sword weapon skill\n-- Skill Level: 50\n-- Deals fire elemental damage to enemy. Damage varies with TP.\n-- Aligned with the Flame Gorget & Breeze Gorget.\n-- Aligned with the Flame Belt & Breeze Belt.\n-- Element: Fire\n-- Modifiers: STR:40%  INT:40%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.38      3.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.38, 3.0 }\n    params.str_wsc = 0.3 params.int_wsc = 0.2\n    params.ele = xi.element.FIRE\n    params.skill = xi.skill.SWORD\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.0, 2.38, 3.75 }\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/refulgent_arrow.lua"]={["Path"]="scripts/actions/weaponskills/refulgent_arrow.lua",["SHA256"]="94f59bf1e05b9dd3a96df5d5c2bb6aa5077017e954bc5cefdd4ace712738e0e5",["Text"]="-----------------------------------\n-- Refulgent Arrow\n-- Archery weapon skill\n-- Skill level: 290\n-- Delivers a twofold attack. Damage varies with TP.\n-- Aligned with the Aqua Gorget & Light Gorget.\n-- Aligned with the Aqua Belt & Light Belt.\n-- Element: None\n-- Modifiers: STR: 60% http://www.bg-wiki.com/bg/Refulgent_Arrow\n-- 100%TP    200%TP    300%TP\n-- 3.00      4.25      7.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 3.0, 4.25, 5.0 }\n    params.str_wsc = 0.16\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 3.0, 4.25, 7.0 }\n        params.str_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/requiescat.lua"]={["Path"]="scripts/actions/weaponskills/requiescat.lua",["SHA256"]="6ed4ace1b17b46afe0fccae6260d11696f8cc84242e364030dcde5f1964e2133",["Text"]="-----------------------------------\n-- Requiescat\n-- Sword weapon skill\n-- Skill level: MERIT\n-- Delivers a five-hit attack. Attack power varies with TP.\n-- Element: None\n-- Modifiers: MND:73~85%\n-- 100%TP    200%TP    300%TP\n--         ALL 1.0\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 5\n    params.ftpMod = { 1.0, 1.0, 1.0 }\n    params.mnd_wsc = player:getMerit(xi.merit.REQUIESCAT) * 0.17\n    params.atkVaries = { 0.8, 0.9, 1.0 }\n    -- TODO: Verify the params.formless check\n    params.formless = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.mnd_wsc = 0.7 + (player:getMerit(xi.merit.REQUIESCAT) * 0.03)\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/resolution.lua"]={["Path"]="scripts/actions/weaponskills/resolution.lua",["SHA256"]="e4edba8efde5d5922808aa2d1767de1aa48044f18cd8d377577c35b7efe93f63",["Text"]="-----------------------------------\n-- Resolution\n-- Great Sword weapon skill\n-- Skill Level: 357\n-- Delivers a fivefold attack. Damage varies with TP.\n-- In order to obtain Resolution, the quest Martial Mastery must be completed.\n-- This Weapon Skill's first hit params.ftp is duplicated for all additional hits.\n-- Resolution has an attack penalty of -8%.\n-- Aligned with the Breeze Gorget, Thunder Gorget & Soil Gorget.\n-- Aligned with the Breeze Belt, Thunder Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:73~85%, depending on merit points upgrades.\n-- 100%TP    200%TP    300%TP\n-- 0.71875    1.5       2.25\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 5\n    params.ftpMod = { 0.71875, 0.84375, 0.96875 }\n    params.str_wsc = player:getMerit(xi.merit.RESOLUTION) * 0.17\n    params.atkVaries = { 0.85, 0.85, 0.85 }\n    params.multiHitfTP = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 0.71875, 1.5, 2.25 }\n        params.str_wsc = 0.7 + (player:getMerit(xi.merit.RESOLUTION) * 0.03)\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/retribution.lua"]={["Path"]="scripts/actions/weaponskills/retribution.lua",["SHA256"]="45cb030bc91ea212084ec691686fa3e37363ea937d38d7317feafd03867ec64f",["Text"]="-----------------------------------\n-- Retribution\n-- Staff weapon skill\n-- Skill Level: 230\n-- Delivers a single-hit attack. Damage varies with TP.\n-- In order to obtain Retribution, the quest Blood and Glory must be completed.\n-- Despite the appearance of throwing the staff, this is not a long-range Weapon Skill like Mistral Axe.\n-- The range only extends the usual 1 yalm beyond meleeing range.\n-- Will stack with Sneak Attack.\n-- Aligned with the Shadow Gorget, Soil Gorget & Aqua Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Aqua Belt.\n-- Element: None\n-- Modifiers: STR:30%  MND:50%\n-- 100%TP    200%TP    300%TP\n-- 2.00      2.50      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params     = {}\n    params.numHits   = 1\n    params.ftpMod    = { 2.0, 2.5, 3.0 }\n    params.atkVaries = { 1.5, 1.5, 1.5 } -- https://w.atwiki.jp/studiogobli/pages/93.html\n    params.str_wsc   = 0.3\n    params.mnd_wsc   = 0.5\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/rock_crusher.lua"]={["Path"]="scripts/actions/weaponskills/rock_crusher.lua",["SHA256"]="2cd8981f14f5e5f87267c476c5cc651cf4362833464da144014216f50796c692",["Text"]="-----------------------------------\n-- Rock Crusher\n-- Staff weapon skill\n-- Skill Level: 40\n-- Delivers an earth elemental attack. Damage varies with TP.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: Earth\n-- Modifiers: STR:40%  INT:40%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.00      2.50\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.0, 2.5 }\n    params.str_wsc = 0.2 params.int_wsc = 0.2\n    params.ele = xi.element.EARTH\n    params.skill = xi.skill.STAFF\n    params.includemab = true\n    params.dStat = xi.mod.INT\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/rudras_storm.lua"]={["Path"]="scripts/actions/weaponskills/rudras_storm.lua",["SHA256"]="314b60d610a13721e527c6a1fbed792ea698040c617c4bc710b22b4042976ccb",["Text"]="-----------------------------------\n-- Rudra's Storm\n-- Dagger weapon skill\n-- Skill level: N/A\n-- Deals triple damage and weighs target down (duration: 60s). Damage varies with TP.\n-- Aligned with the Aqua Gorget, Snow Gorget & Shadow Gorget.\n-- Aligned with the Aqua Belt, Snow Belt & Shadow Belt.\n-- Element: None\n-- Modifiers: DEX:80%\n-- 100%TP    200%TP    300%TP\n-- 6          15        19.5\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 3.25, 4.25, 5.25 }\n    params.dex_wsc = 0.6\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 5, 10.19, 13 }\n        params.dex_wsc = 0.8\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.EMPYREAN)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.WEIGHT\n    local actionElement = xi.element.WIND\n    local power         = 25\n    local duration      = 60\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/ruinator.lua"]={["Path"]="scripts/actions/weaponskills/ruinator.lua",["SHA256"]="60319e236db997e2fc7afe9e631a154fffc6c6c883c27248f02eb137fe04b122",["Text"]="-----------------------------------\n-- Ruinator\n-- Axe weapon skill\n-- Skill level: 357\n-- Description: Delivers a four-hit attack. params.accuracy varies with TP\n-- In order to obtain Ruinator, the quest Martial Mastery must be completed.\n-- This Weapon Skill's first hit params.ftp is duplicated for all additional hits\n-- Aligned with the Aqua Gorget, Snow Gorget & Breeze Gorget\n-- Aligned with the Aqua Belt, Snow Belt & Breeze Belt.\n-- Element: None\n-- Modifiers: STR:73~85%, depending on merit points upgrades.\n-- 100%TP    200%TP    300%TP\n-- 1.08       1.08      1.08\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 4\n    params.ftpMod = { 1.08, 1.08, 1.08 }\n    params.str_wsc = player:getMerit(xi.merit.RUINATOR) * 0.17\n    params.accVaries = { 0, 30, 60 } -- TODO: verify exact number\n    params.atkVaries = { 1.1, 1.1, 1.1 }\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.7 + (player:getMerit(xi.merit.RUINATOR) * 0.03)\n        params.multiHitfTP = true\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/sanguine_blade.lua"]={["Path"]="scripts/actions/weaponskills/sanguine_blade.lua",["SHA256"]="e3abd85479ac6a8f9a4571e295fa1082ef3533f834709ca945eb3449a7e54499",["Text"]="-----------------------------------\n-- Sanguine Blade\n-- Sword weapon skill\n-- Skill Level: 300\n-- Drains a percentage of damage dealt to HP varies with TP.\n-- Will not stack with Sneak Attack.\n-- Not aligned with any \"elemental gorgets\" or \"elemental belts\" due to it's absence of Skillchain properties.\n-- Element: Dark\n-- Modifiers: STR:30%  MND:50%\n-- 100%TP    200%TP    300%TP\n-- 2.75      2.75      2.75\n-- HP Drained by TP:\n-- 100%TP    200%TP    300%TP\n-- 50%       75%    100%\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local drain = 25 + math.floor(tp / 1000) * 25\n    local params = {}\n    params.ftpMod = { 2.75, 2.75, 2.75 }\n    params.str_wsc = 0.3 params.mnd_wsc = 0.5\n    params.ele = xi.element.DARK\n    params.skill = xi.skill.SWORD\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        if tp >= 2000 and tp <= 2999 then\n            drain = 100\n        elseif tp == 3000 then\n            drain = 160\n        end\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n\n    if not target:isUndead() then\n        player:addHP((damage / 100) * drain)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/savage_blade.lua"]={["Path"]="scripts/actions/weaponskills/savage_blade.lua",["SHA256"]="6e0dabb2df09164b72d6a940822912da27e599f9c165632431c1b99d21921479",["Text"]="-----------------------------------\n-- Savage Blade\n-- Sword weapon skill\n-- Skill Level: 240\n-- Delivers an aerial attack comprised of two hits. Damage varies with TP.\n-- In order to obtain Savage Blade, the quest Old Wounds must be completed.\n-- Will stack with Sneak Attack.\n-- Aligned with the Breeze Gorget, Thunder Gorget & Soil Gorget\n-- Aligned with the Breeze Belt, Thunder Belt & Soil Belt.\n-- Element: None\n-- Modifiers: STR:50%  MND:50%\n-- 100%TP    200%TP    300%TP\n-- 4.00      10.25      13.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 1.0, 1.75, 3.5 }\n    params.str_wsc = 0.3 params.mnd_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 4.0, 10.25, 13.75 }\n        params.str_wsc = 0.5\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/scourge.lua"]={["Path"]="scripts/actions/weaponskills/scourge.lua",["SHA256"]="dd538ed3793fe4bc26e3ba3fde7856eff8a58be90c72171f1a453c2992824400",["Text"]="    -----------------------------------\n-- Scourge\n-- Great Sword weapon skill\n-- Skill level: N/A\n-- Additional effect: temporarily improves params.critical hit rate.\n-- params.critical hit rate boost duration is based on TP when the weapon skill is used. 100% TP will give 20 seconds of params.critical hit rate boost this scales linearly to 60 seconds of params.critical hit rate boost at 300% TP. 5 TP = 1 Second of Aftermath.\n-- Parses show the params.critical hit rate increase from the Scourge Aftermath is between 10% and 15%.\n-- This weapon skill is only available with the stage 5 relic Great Sword Ragnarok or within Dynamis with the stage 4 Valhalla.\n-- Aligned with the Light Gorget & Flame Gorget.\n-- Aligned with the Light Belt & Flame Belt.\n-- Element: None\n-- Modifiers: STR:40%  VIT:40%\n-- 100%TP    200%TP    300%TP\n-- 3.00      3.00      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 1\n    params.ftpMod = { 3.0, 3.0, 3.0 }\n    params.mnd_wsc = 0.4 params.chr_wsc = 0.4\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.vit_wsc = 0.4 params.mnd_wsc = 0.0 params.chr_wsc = 0.0\n    end\n\n    -- Apply aftermath\n    xi.aftermath.addStatusEffect(player, tp, xi.slot.MAIN, xi.aftermath.type.RELIC)\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/seraph_blade.lua"]={["Path"]="scripts/actions/weaponskills/seraph_blade.lua",["SHA256"]="3d74fac61afdd3ce74353cc01f0d8a8e219e5df921a36f8f17c88a6217d5337e",["Text"]="-----------------------------------\n-- Seraph Blade\n-- Sword weapon skill\n-- Skill Level: 125\n-- Deals light elemental damage to enemy. Damage varies with TP.\n-- Ignores shadows.\n-- Aligned with the Soil Gorget.\n-- Aligned with the Soil Belt.\n-- Element: Light\n-- Modifiers: STR:40%  MND:40%\n-- 100%TP    200%TP    300%TP\n-- 1.125      2.625      4.125\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.5, 3.0 }\n    params.str_wsc = 0.3 params.mnd_wsc = 0.3\n    params.ele = xi.element.LIGHT\n    params.skill = xi.skill.SWORD\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 1.125, 2.625, 4.125 }\n        params.str_wsc = 0.4 params.mnd_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/seraph_strike.lua"]={["Path"]="scripts/actions/weaponskills/seraph_strike.lua",["SHA256"]="7839565c9b2f2e9f150cd3754cc2919f86f3a91b8abd4fa1584d0cbbc66fa659",["Text"]="-----------------------------------\n-- Seraph Strike\n-- Club weapon skill\n-- Skill level: 40\n-- Deals light elemental damage to enemy. Damage varies with TP.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: None\n-- Modifiers: STR:40%  MND:40%\n-- 100%TP    200%TP    300%TP\n-- 2.125     3.675      6.125\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.0, 3.0 }\n    params.str_wsc = 0.3 params.mnd_wsc = 0.3\n    params.ele = xi.element.LIGHT\n    params.skill = xi.skill.CLUB\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 2.125, 3.675, 6.125 }\n        params.str_wsc = 0.4 params.mnd_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shadow_of_death.lua"]={["Path"]="scripts/actions/weaponskills/shadow_of_death.lua",["SHA256"]="7145d90fe14112bd939ec3ec69724f7ef7cf1bc22bdb6e43b7adaf861c383157",["Text"]="-----------------------------------\n-- Shadow of Death\n-- Scythe weapon skill\n-- Skill Level: 70\n-- Delivers a dark elemental attack. Damage varies with TP.\n-- Aligned with the Snow Gorget & Aqua Gorget.\n-- Aligned with the Snow Belt & Aqua Belt.\n-- Element: Dark\n-- Modifiers: STR:40%  INT:40%\n-- 100%TP    200%TP    300%TP\n-- 1.00      2.50      3.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.ftpMod = { 1.0, 2.5, 3.0 }\n    params.str_wsc = 0.3 params.int_wsc = 0.3\n    params.ele = xi.element.DARK\n    params.skill = xi.skill.SCYTHE\n    params.includemab = true\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.4 params.int_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doMagicWeaponskill(player, target, wsID, params, tp, action, primary)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shadowstitch.lua"]={["Path"]="scripts/actions/weaponskills/shadowstitch.lua",["SHA256"]="ba8cf0772862be12aa3fe2c39ad71476d6a3268327f8bd77161aa6349e69cdc5",["Text"]="-----------------------------------\n-- Shadowstitch\n-- Dagger weapon skill\n-- Skill level: 70\n-- Binds target. Chance of binding varies with TP.\n-- Does stack with Sneak Attack.\n-- Aligned with the Aqua Gorget.\n-- Aligned with the Aqua Belt.\n-- Element: None\n-- Modifiers: CHR:100%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.chr_wsc = 0.3\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.chr_wsc = 1\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    if math.randomInt(1, 100) <= tp / 30 * applyResistanceAddEffect(player, target, xi.element.ICE, 0) then\n        local effectId      = xi.effect.BIND\n        local actionElement = xi.element.ICE\n        local power         = 1\n        local duration      = math.floor((5 + tp / 200) * applyResistanceAddEffect(player, target, actionElement, 0))\n        xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n    end\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shark_bite.lua"]={["Path"]="scripts/actions/weaponskills/shark_bite.lua",["SHA256"]="9a6e6e0196c41339baa0c1ea186bd1fc1c29aec7fe238053ab0fe33496ac6ec6",["Text"]="-----------------------------------\n-- Shark Bite\n-- Dagger weapon skill\n-- Skill level: 225\n-- Delivers a twofold attack. Damage varies with TP.\n-- Will stack with Sneak Attack.\n-- Will stack with Trick Attack.\n-- Aligned with the Breeze Gorget & Thunder Gorget.\n-- Aligned with the Breeze Belt & Thunder Belt.\n-- Element: None\n-- Modifiers: DEX:40% AGI:40%\n-- 100%TP    200%TP    300%TP\n--  2.00       4        5.75\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params = {}\n    params.numHits = 2\n    params.ftpMod = { 2.0, 2.5, 3.0 }\n    params.dex_wsc = 0.5\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.ftpMod = { 4.5, 6.8, 8.5 }\n        params.dex_wsc = 0.4 params.agi_wsc = 0.4\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shattersoul.lua"]={["Path"]="scripts/actions/weaponskills/shattersoul.lua",["SHA256"]="bbf7795b0fb1912de86443e1b6d1536e851ce90819b3950081559ade7692cdce",["Text"]="-----------------------------------\n-- Shattersoul\n-- Skill Level: 357\n-- Description: Delivers a threefold attack. Decreases target's magic defense. Duration of effect varies with TP.\n-- To obtain Shattersoul, the quest Martial Mastery must be completed and it must be purchased from the Merit Points menu.\n-- Target's magic defense is lowered by 10.\n-- Aligned with the Shadow Gorget, Soil Gorget & Snow Gorget.\n-- Aligned with the Shadow Belt, Soil Belt & Snow Belt.\n-- Element: N/A\n-- Skillchain Properties: Gravitation/Induration\n-- Shattersoul is only available to Warriors, Monks, White Mages, Black Mages, Paladins, Bards, Dragoons, Summoners and Scholars.\n-- While some jobs may obtain skill level 357 earlier than level 96, Shattersoul must be unlocked once skill reaches level 357 and job level 96 is reached.\n-- Staff skill level 357 is obtainable by the following jobs at these corresponding levels:\n-- Modifiers: INT:73~85%, depending on merit points upgrades.\n-- Damage Multipliers by TP:\n-- 100%TP    200%TP    300%TP\n-- 1.375      1.375      1.375\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 3\n    params.ftpMod  = { 1.375, 1.375, 1.375 }\n    params.int_wsc = player:getMerit(xi.merit.SHATTERSOUL) * 0.17\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.int_wsc = 0.7 + player:getMerit(xi.merit.SHATTERSOUL) * 0.03\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.MAGIC_DEF_DOWN\n    local actionElement = xi.element.THUNDER\n    local power         = 10\n    local duration      = math.floor(120 * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shell_crusher.lua"]={["Path"]="scripts/actions/weaponskills/shell_crusher.lua",["SHA256"]="e9390796baef74d1b9977e0eb30f83e24fe70904d439b25bfad3879cde6398c8",["Text"]="-----------------------------------\n-- Shell Crusher\n-- Staff weapon skill\n-- Skill Level: 175\n-- Lowers target's defense. Duration of effect varies with TP.\n-- If unresisted, lowers target defense by 25%.\n-- Will stack with Sneak Attack.\n-- Aligned with the Breeze Gorget.\n-- Aligned with the Breeze Belt.\n-- Element: None\n-- Modifiers: STR:100%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.35\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 1\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.DEFENSE_DOWN\n    local actionElement = xi.element.WIND\n    local power         = 25\n    local duration      = math.floor((120 + 6 * tp / 100) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"},["scripts/actions/weaponskills/shield_break.lua"]={["Path"]="scripts/actions/weaponskills/shield_break.lua",["SHA256"]="205e6c56c5ed233d32a77984acca66b1dc027508ad1d7e9bc987b907acdceade",["Text"]="-----------------------------------\n-- Shield Break\n-- Great Axe weapon skill\n-- Skill level: 5\n-- Lowers enemy's Evasion. Duration of effect varies with TP.\n-- Lowers Evasion by as much as 40 if unresisted.\n-- Strong against: Bees, Beetles, Birds, Crabs, Crawlers, Flies, Lizards, Mandragora, Opo-opo, Pugils, Sabotenders, Scorpions, Sea Monks, Spiders, Tonberry, Yagudo.\n-- Immune: Bombs, Gigas, Ghosts, Sheep, Skeletons, Tigers.\n-- Will stack with Sneak Attack.\n-- Aligned with the Thunder Gorget.\n-- Aligned with the Thunder Belt.\n-- Element: Ice\n-- Modifiers: STR:60%  VIT:60%\n-- 100%TP    200%TP    300%TP\n-- 1.00      1.00      1.00\n-----------------------------------\n---@type TWeaponSkill\nlocal weaponskillObject = {}\n\nweaponskillObject.onUseWeaponSkill = function(player, target, wsID, tp, primary, action, taChar)\n    local params   = {}\n    params.numHits = 1\n    params.ftpMod  = { 1, 1, 1 }\n    params.str_wsc = 0.2\n    params.vit_wsc = 0.2\n\n    if xi.settings.main.USE_ADOULIN_WEAPON_SKILL_CHANGES then\n        params.str_wsc = 0.6\n        params.vit_wsc = 0.6\n    end\n\n    local damage, criticalHit, tpHits, extraHits = xi.weaponskills.doPhysicalWeaponskill(player, target, wsID, params, tp, action, primary, taChar)\n\n    -- Handle status effect\n    local effectId      = xi.effect.EVASION_DOWN\n    local actionElement = xi.element.ICE\n    local power         = 40\n    local duration      = math.floor((120 + 6 * tp / 100) * applyResistanceAddEffect(player, target, actionElement, 0))\n    xi.weaponskills.handleWeaponskillEffect(player, target, effectId, actionElement, damage, power, duration)\n\n    return tpHits, extraHits, criticalHit, damage\nend\n\nreturn weaponskillObject\n"}};
